33	  private _idbRequestToPromise<T extends IDBOpenDBRequest | IDBRequest>(request: T) {
34	    return new Promise<T['result']>((resolve, reject) => {
35	      request.addEventListener('success', () => resolve(request.result));
36	      request.addEventListener('error', () => reject(request.error));
37	    });
38	  }
