226	  private async _restoreOPFS(originState: SetOriginStorage | undefined) {
227	    let root: FileSystemDirectoryHandle;
228	    try {
229	      root = await this._global.navigator.storage.getDirectory();
230	    } catch (e) {
231	      // OPFS may be unavailable, e.g. on insecure origins or in WebKit contexts
232	      // that fail with 'unknown transient reason'. There is nothing to clear then,
233	      // so only fail when there are entries to restore.
234	      if (originState?.opfs === undefined)
235	        return;
236	      throw e;
237	    }
238	
239	    await Promise.all((await this._directoryEntries(root)).map(([name]) => root.removeEntry(name, { recursive: true })));
240	
241	    const entries = originState?.opfs ?? [];
242	    if (!entries.length)
243	      return;
244	
245	    for (const entry of entries) {
246	      const parts = entry.path.split('/');
247	      let directory = root;
248	      for (const part of parts.slice(0, -1))
249	        directory = await directory.getDirectoryHandle(part, { create: true });
250	
251	      const name = parts[parts.length - 1];
252	      if (entry.type === 'directory') {
253	        await directory.getDirectoryHandle(name, { create: true });
254	        continue;
255	      }
256	      const blob = await this._blobFromBase64(entry.base64!);
257	      const handle = await directory.getFileHandle(name, { create: true });
258	      const writable = await handle.createWritable();
259	      await writable.write(blob);
260	      await writable.close();
261	    }
262	  }
263	
264	  // Decode through the page's own fetch so that the resulting blob belongs to the page.
265	  // The Firefox utility world is a sandbox with an extended principal, so the page is
266	  // denied access to objects allocated here and writing a Uint8Array built in this world
267	  // fails with 'Permission denied to access property "data"'.
268	  private async _blobFromBase64(base64: string): Promise<Blob> {
269	    const response = await this._global.fetch(`data:application/octet-stream;base64,${base64}`);
270	    return response.blob();
271	  }
272	
273	  async restore(originState: SetOriginStorage | undefined) {
274	    // Clean Service Workers.
275	    const registrations = this._global.navigator.serviceWorker ? await this._global.navigator.serviceWorker.getRegistrations() : [];
276	    await Promise.all(registrations.map(async r => {
277	      // Heuristic for service workers that stalled during main script fetch or importScripts:
278	      // Waiting for them to finish unregistering takes ages so we do not await.
279	      // However, they will unregister immediately after fetch finishes and should not affect next page load.
280	      // Unfortunately, loading next page in Chromium still takes 5 seconds waiting for
281	      // some operation on this bogus service worker to finish.
282	      if (!r.installing && !r.waiting && !r.active)
283	        r.unregister().catch(() => {});
284	      else
285	        await r.unregister().catch(() => {});
286	    }));
287	
288	    try {
289	      for (const db of await this._global.indexedDB.databases?.() || []) {
290	        // Do not wait for the callback - it is called on timer in Chromium (slow).
291	        if (db.name)
